def step_round(state, width, height, target):
    result = state.copy()
    if result["winner"] is not None:
        return result
    if result["x"] + 8 <= 0:
        player = "right"
    elif result["x"] - 8 >= width:
        player = "left"
    else:
        return result
    result[player] += 1
    result["x"], result["y"] = width / 2, height / 2
    if result[player] >= target:
        result["winner"] = player
        result["vx"], result["vy"] = 0, 0
    else:
        result["vx"] = 180 if player == "right" else -180
        result["vy"] = 120
    return result
